import 'dart:convert';
import 'boarding_drop_scan_event.dart';
class OfflineTransportScanQueue { final Map<String, OfflineTransportScanQueueEntry> _entries = {}; Future<void> enqueue(BoardingDropScanEvent event) async { _entries.putIfAbsent(event.clientScanId, () => OfflineTransportScanQueueEntry(event: event, state: OfflineTransportScanState.pending)); } Future<List<OfflineTransportScanQueueEntry>> pending() async => _entries.values.where((entry) => entry.state == OfflineTransportScanState.pending).toList(growable: false); Future<void> markSynced(String clientScanId) async => _mark(clientScanId, OfflineTransportScanState.synced); Future<void> markRejected(String clientScanId) async => _mark(clientScanId, OfflineTransportScanState.rejected); Future<void> _mark(String clientScanId, OfflineTransportScanState state) async { final entry = _entries[clientScanId]; if (entry != null) { _entries[clientScanId] = OfflineTransportScanQueueEntry(event: entry.event, state: state); } } String encodePayload(BoardingDropScanEvent event) => jsonEncode(event.toJson()); }
